  "search_recency_filter": "month"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "Find workshop and demo track CFPs at AI conferences specifically about {{ $json.research_topics }} in 2026. These are easier entry points for first publications. Include deadlines, acceptance rates where known, and whether they are archival."}],
